def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separate the input string into separate groups of correctly nested parentheses.
    Args:
        paren_string (str): The input string containing parentheses.
    Returns:
        List[str]: A list of strings containing the separate parentheses groups.
    """
    groups = []
    current_group = ""
    stack = []
    for char in paren_string:
        if char == "(":
            if not stack:
                current_group += char
                stack.append(char)
            else:
                current_group += char
                stack.append(char)
        elif char == ")":
            if stack:
                current_group += char
                stack.pop()
            else:
                raise ValueError("Invalid input: Unbalanced parentheses")
        else:
            continue
    if stack:
        raise ValueError("Invalid input: Unbalanced parentheses")
    groups.append(current_group)
    return groups
