def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a 2D table to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Base case: dp[i][0] = 0 for all i
    for i in range(V + 1):
        dp[i][0] = 0

    # Fill in the table using the recurrence relation
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            if volumes[j - 1] <= i:
                dp[i][j] = max(dp[i - volumes[j - 1]][j - 1], dp[i][j - 1])
            else:
                dp[i][j] = dp[i][j - 1]

    # Return the minimum remaining space as the difference between the total capacity and the maximum occupied volume
    return V - dp[V][n]
```

